import{_ as s,l as o,o as a,c as r,v as t,p as c,x as i,d as l,i as n,S as u}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"setuid 与粘滞位","description":"","frontmatter":{"title":"setuid 与粘滞位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/setuid-sticky.md","filePath":"cs/setuid-sticky.md","lastUpdated":1789023840000}'),p={name:"cs/setuid-sticky.md"};function h(m,e,E,B,_,f){const d=o("Mermaid");return a(),r("div",null,[e[1]||(e[1]=t('<h1 id="setuid-与粘滞位" tabindex="-1">setuid 与粘滞位 <a class="header-anchor" href="#setuid-与粘滞位" aria-label="Permalink to &quot;setuid 与粘滞位&quot;">​</a></h1><div class="epigraph"><p>setuid 可执行文件在 exec 后把有效用户换成文件属主；粘滞目录只允许用户删除自己的目录项。</p><footer>—— 据 Ritchie and Thompson 对 setuid 的原始设计；Bach；POSIX 整理</footer></div><p><a href="/cs/file-mode-bits">上一课</a>按有效身份检查 rwx。有些程序需要暂时以另一用户访问文件（口令改密），但不能把该用户的口令写进所有调用者。<a href="/cs/process-image">进程映像</a> 的 exec 会换映像。缺口是 <strong>setuid/setgid 与粘滞位</strong>：改有效身份，以及 <code>/tmp</code> 上的删除规则。本课讲机制，不讲如何利用错误配置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 passwd 必须以 root 写口令文件，又必须以普通用户调用，缺口是 exec 时把有效 uid 设为二进制文件的属主（通常 root），真实 uid 仍记录调用者。内核在打开文件时用有效 uid。粘滞位在目录上：即使目录可写，也不得删别人的文件名。setgid 对文件类似换有效 gid；对目录可表示「新建文件继承目录组」。</p><p>本课不把 Linux 文件能力（capabilities）的全部位图写完。</p><p><span class="marginnote">解释器脚本的 setuid 历史上不安全，许多系统忽略脚本上的 setuid。可执行映像才提升。本课不给绕过步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>chmod u+s</code>：mode 里 setuid 位置位。<code>execve</code> 通过 <a href="/cs/file-mode-bits">模式</a> 的 x 检查后，若 setuid 则 euid←属主。后续 <code>open</code> 用 euid。程序可 <code>seteuid</code> 在真实与有效之间收放（受规则限制）。粘滞目录：<code>unlink</code>/<code>rename</code> 额外检查调用者是否为目录项属主或有特权。VFS 在这些系统调用里执行检查，FS 只存那一位。</p>',9)),(a(),c(u,null,{default:i(()=>[n(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXEC%5B%22exec%20%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%96%87%E4%BB%B6%22%5D%20--%3E%20SUID%7B%22setuid%3F%22%7D%0A%20%20SUID%20--%3E%7C%E6%98%AF%7C%20EUID%5B%22euid%20%3D%20%E6%96%87%E4%BB%B6%E5%B1%9E%E4%B8%BB%22%5D%0A%20%20STICK%5B%22%E7%B2%98%E6%BB%9E%E7%9B%AE%E5%BD%95%20unlink%22%5D%20--%3E%20OWN%5B%22%E9%A1%BB%E6%98%AF%E8%AF%A5%E9%A1%B9%E5%B1%9E%E4%B8%BB%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>setuid 是受控的身份切换，把「需特权的操作」收进特定二进制，而不是给用户永久 root。粘滞位修复「目录可写则人人可删别人文件」。两者都是 mode 的额外位，不改页表。<a href="/cs/syscall-path">系统调用路径</a> 上检查发生在 VFS，与具体 ext4 日志无关。</p><p>安全课会谈最小特权与审计；本课只把位接到 exec 与 unlink。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析具体漏洞，不讲提权步骤。nosuid 挂载可忽略 setuid，容器课会再提。下一课离开权限，进入块层：许多已经允许的读写，请求如何排序送向设备。</p><p>后课默认：身份与 <code>/tmp</code> 规则已定。块请求的电梯与多队列，下一课磁盘调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>setuid 在 exec 时改 euid；粘滞位限制可写目录上的删除。</li><li>检查在 VFS；本课不讲利用。</li><li>块层调度是下一课。</li><li>出处：Ritchie and Thompson；Bach, <em>UNIX</em>；POSIX。</li></ul>',8))])}const S=s(p,[["render",h]]);export{A as __pageData,S as default};
